1: package com.example.Used.Service;
2: 
3: import org.springframework.stereotype.Service;
4: import org.springframework.web.servlet.mvc.method.annotation.SseEmitter;
5: 
6: import java.io.IOException;
7: import java.util.List;
8: import java.util.Map;
9: import java.util.concurrent.ConcurrentHashMap;
10: import java.util.concurrent.CopyOnWriteArrayList;
11: 
12: @Service
13: public class NotificationService {
14: 
15:     private final Map<Long, List<SseEmitter>> emittersByUser = new ConcurrentHashMap<>();
16: 
17:     public SseEmitter subscribe(Long userId) {
18: 
19:         SseEmitter emitter = new SseEmitter(Long.MAX_VALUE);
20: 
21:         // add to this user's bucket (create bucket if first connection)
22:         emittersByUser
23:                 .computeIfAbsent(userId, k -> new CopyOnWriteArrayList<>())
24:                 .add(emitter);
25: 
26:         // on disconnect, remove THIS emitter from THIS user's bucket
27:         Runnable cleanup = () -> {
28:             List<SseEmitter> bucket = emittersByUser.get(userId);
29:             if (bucket != null) {
30:                 bucket.remove(emitter);
31:                 if (bucket.isEmpty()) {
32:                     emittersByUser.remove(userId, bucket); // drop empty bucket
33:                 }
34:             }
35:         };
36:         emitter.onCompletion(() -> removeEmitter(userId, emitter));
37:         emitter.onTimeout(() -> removeEmitter(userId, emitter));
38:         emitter.onError((e) -> removeEmitter(userId, emitter));
39: 
40:         try {
41:             emitter.send(SseEmitter.event()
42:                     .name("CONNECTED")
43:                     .data("Subscribed as user " + userId));
44:         } catch (IOException e) {
45:             cleanup.run();
46:         }
47: 
48:         return emitter;
49:     }
50: 
51:     private void removeEmitter(Long userId, SseEmitter emitter) {
52:         List<SseEmitter> emitters = emittersByUser.get(userId);
53:         if (emitters != null) {
54:             emitters.remove(emitter);
55:             if (emitters.isEmpty()) {
56:                 emittersByUser.remove(userId);
57:             }
58:         }
59:     }
60: 
61: 
62:     public void sendToUser(Long userId, String eventName, Object data) {
63:         List<SseEmitter> emitters = emittersByUser.get(userId);
64:         if (emitters != null && !emitters.isEmpty()) {
65:             for (SseEmitter emitter : emitters) {
66:                 try {
67:                     emitter.send(SseEmitter.event()
68:                             .name(eventName)
69:                             .data(data));
70:                 } catch (IOException e) {
71:                     // Remove broken connections
72:                     removeEmitter(userId, emitter);
73:                 }
74:             }
75:         }
76:     }
77: 
78:     public void broadcast(String eventName, Object data) {
79:         emittersByUser.values().forEach(bucket ->
80:                 bucket.removeIf(emitter -> {
81:                     try {
82:                         emitter.send(SseEmitter.event().name(eventName).data(data));
83:                         return false;
84:                     } catch (IOException e) {
85:                         return true;
86:                     }
87:                 })
88:         );
89:     }
90: 
91: }

