const fs = require('fs');
const zlib = require('zlib');

const buf = fs.readFileSync(process.argv[2]);
const latin1 = buf.toString('latin1');

function decodePdfString(s) {
  let out = '';
  for (let i = 0; i < s.length; i++) {
    const c = s[i];
    if (c === '\\') {
      const n = s[++i];
      if (n === 'n') out += '\n';
      else if (n === 'r') out += '\r';
      else if (n === 't') out += '\t';
      else if (n === 'b' || n === 'f') out += '';
      else if (n >= '0' && n <= '7') {
        let oct = n;
        while (oct.length < 3 && s[i + 1] >= '0' && s[i + 1] <= '7') oct += s[++i];
        out += String.fromCharCode(parseInt(oct, 8));
      } else if (n === '\n') { /* line continuation */ }
      else out += n;
    } else out += c;
  }
  return out;
}

function hexToString(hex) {
  hex = hex.replace(/[^0-9a-fA-F]/g, '');
  let out = '';
  for (let i = 0; i + 1 < hex.length; i += 2) out += String.fromCharCode(parseInt(hex.substr(i, 2), 16));
  return out;
}

// gather all stream bodies
const streams = [];
const re = /stream\r?\n/g;
let m;
while ((m = re.exec(latin1)) !== null) {
  const start = m.index + m[0].length;
  const end = latin1.indexOf('endstream', start);
  if (end === -1) continue;
  streams.push(buf.slice(start, end));
}

const texts = [];
for (const raw of streams) {
  let content = null;
  try { content = zlib.inflateSync(raw); } catch (e) {
    try { content = zlib.inflateRawSync(raw); } catch (e2) { continue; }
  }
  const s = content.toString('latin1');
  // skip binary/font streams that have no text operators
  if (!/\b(Tj|TJ|Tf|BT)\b/.test(s)) continue;

  // capture text within BT..ET blocks roughly, honoring T* / TD as newlines
  const tokenRe = /\((?:\\[\s\S]|[^\\()])*\)|<[0-9a-fA-F\s]+>|\[[\s\S]*?\]\s*TJ|T\*|Td|TD|ET|BT/g;
  let line = '';
  let t;
  while ((t = tokenRe.exec(s)) !== null) {
    const tok = t[0];
    if (tok.startsWith('(')) line += decodePdfString(tok.slice(1, -1));
    else if (tok.startsWith('<')) line += hexToString(tok.slice(1, -1));
    else if (tok.startsWith('[')) {
      const inner = tok;
      const partRe = /\((?:\\[\s\S]|[^\\()])*\)|<[0-9a-fA-F\s]+>|-?\d+(\.\d+)?/g;
      let p;
      while ((p = partRe.exec(inner)) !== null) {
        if (p[0].startsWith('(')) line += decodePdfString(p[0].slice(1, -1));
        else if (p[0].startsWith('<')) line += hexToString(p[0].slice(1, -1));
        else {
          const n = parseFloat(p[0]);
          if (n < -150) line += ' ';
        }
      }
    } else if (tok === 'T*' || tok === 'Td' || tok === 'TD') {
      if (line.trim()) texts.push(line);
      line = '';
    }
  }
  if (line.trim()) texts.push(line);
}
console.log(texts.join('\n'));

const fs = require('fs');
const buf = fs.readFileSync(process.argv[2]);
const l = buf.toString('latin1');

// ---- parse objects (PDF here is uncompressed) ----
const objs = {};
const objRe = /(\d+)\s+(\d+)\s+obj([\s\S]*?)endobj/g;
let m;
while ((m = objRe.exec(l)) !== null) {
  objs[parseInt(m[1])] = m[3];
}

function streamBody(objText) {
  const i = objText.indexOf('stream');
  if (i < 0) return null;
  const s = i + 'stream'.length;
  const start = objText[s] === '\r' ? s + 2 : s + 1;
  const e = objText.lastIndexOf('endstream');
  if (e < 0 || e < start) return null;
  return objText.slice(start, e);
}

// ---- build ToUnicode maps: fontObjNum -> Map(code->string) ----
function parseCMap(text) {
  const map = new Map();
  let mm;
  const charRe = /beginbfchar([\s\S]*?)endbfchar/g;
  while ((mm = charRe.exec(text)) !== null) {
    const pairRe = /<([0-9a-fA-F]+)>\s*<([0-9a-fA-F]+)>/g;
    let p;
    while ((p = pairRe.exec(mm[1])) !== null) {
      map.set(p[1].toLowerCase(), hexToStr(p[2]));
    }
  }
  const rangeRe = /beginbfrange([\s\S]*?)endbfrange/g;
  while ((mm = rangeRe.exec(text)) !== null) {
    const itemRe = /<([0-9a-fA-F]+)>\s*<([0-9a-fA-F]+)>\s*(?:<([0-9a-fA-F]+)>|\[([\s\S]*?)\])/g;
    let p;
    while ((p = itemRe.exec(mm[1])) !== null) {
      const lo = parseInt(p[1], 16), hi = parseInt(p[2], 16);
      if (p[3]) {
        const base = parseInt(p[3], 16);
        for (let c = lo; c <= hi && c - lo < 65536; c++) {
          map.set(c.toString(16).padStart(p[1].length, '0'), String.fromCodePoint(base + (c - lo)));
        }
      } else if (p[4]) {
        const dests = p[4].match(/<([0-9a-fA-F]+)>/g) || [];
        for (let c = lo; c <= hi && c - lo < dests.length; c++) {
          map.set(c.toString(16).padStart(p[1].length, '0'), hexToStr(dests[c - lo].slice(1, -1)));
        }
      }
    }
  }
  return map;
}
function hexToStr(h) {
  h = h.replace(/\s/g, '');
  let out = '';
  for (let i = 0; i + 1 < h.length; i += 2) out += String.fromCharCode(parseInt(h.substr(i, 2), 16));
  return out;
}

const fontMaps = {}; // font resource name (F17) -> Map
const fontObjToMap = {};
function mapForFontObj(num) {
  if (fontObjToMap[num]) return fontObjToMap[num];
  const o = objs[num];
  let map = new Map();
  if (o) {
    const tu = o.match(/\/ToUnicode\s+(\d+)\s+0\s+R/);
    if (tu) {
      const cm = objs[parseInt(tu[1])];
      const body = cm && streamBody(cm);
      if (body) map = parseCMap(body);
    }
  }
  fontObjToMap[num] = map;
  return map;
}

// ---- walk pages, resolving font resources ----
const pages = [];
for (const num of Object.keys(objs)) {
  const o = objs[num];
  if (/\/Type\s*\/Page[^s]/.test(o) || /\/Type\s*\/Page\s*$/.test(o) || /\/Type\s*\/Page\b/.test(o)) {
    pages.push({ num: parseInt(num), o });
  }
}

function fontDictFrom(resText) {
  const out = {};
  if (!resText) return out;
  let fm = resText.match(/\/Font\s*<<([\s\S]*?)>>/);
  if (!fm) {
    const ref = resText.match(/\/Font\s+(\d+)\s+0\s+R/);
    if (ref && objs[ref[1]]) fm = { 1: objs[ref[1]] };
  }
  if (fm) {
    const pairRe = /(\/F\d+)\s+(\d+)\s+0\s+R/g;
    let p;
    while ((p = pairRe.exec(fm[1])) !== null) out[p[1].slice(1)] = mapForFontObj(parseInt(p[2]));
  }
  return out;
}

const lines = [];
for (const page of pages.sort((a, b) => a.num - b.num)) {
  const contentRef = page.o.match(/\/Contents\s+(\d+)\s+0\s+R/);
  if (!contentRef) continue;
  const contentObj = objs[parseInt(contentRef[1])];
  const body = contentObj && streamBody(contentObj);
  if (!body) continue;

  // resources (may be indirect)
  let resText = null;
  const rs = page.o.match(/\/Resources\s+(\d+)\s+0\s+R/);
  if (rs) resText = objs[parseInt(rs[1])];
  else {
    const ri = page.o.match(/\/Resources\s*<<([\s\S]*?)>>/);
    if (ri) resText = '<<' + ri[1] + '>>';
  }
  const fonts = fontDictFrom(resText);

  let cur = null;
  const tokRe = /\/F\d+\s+[\d.]+\s+Tf|<[0-9a-fA-F]+>\s*Tj|\[[\s\S]*?\]\s*TJ|T\*|-?[\d.]+\s+-?[\d.]+\s+Td|-?[\d.]+\s+-?[\d.]+\s+-?[\d.]+\s+-?[\d.]+\s+-?[\d.]+\s+-?[\d.]+\s+Tm|ET|BT/g;
  let line = '', lastY = null, t;
  while ((t = tokRe.exec(body)) !== null) {
    const tok = t[0];
    if (tok.startsWith('/F')) {
      const name = tok.match(/(\/F\d+)/)[1].slice(1);
      cur = fonts[name] || null;
    } else if (/^<.+>\s*Tj$/.test(tok)) {
