const fs = require('fs');
const l = fs.readFileSync(process.argv[2]).toString('latin1');

// ---------- object parsing ----------
const objs = {};
const objRe = /(\d+)\s+(\d+)\s+obj([\s\S]*?)endobj/g;
let m;
while ((m = objRe.exec(l)) !== null) objs[parseInt(m[1])] = m[3];

function streamBody(t) {
  const i = t.indexOf('stream');
  if (i < 0) return null;
  const s = i + 6;
  const start = t[s] === '\r' ? s + 2 : s + 1;
  const e = t.lastIndexOf('endstream');
  return e > start ? t.slice(start, e) : null;
}
function hexToStr(h) {
  h = h.replace(/\s/g, '');
  let out = '';
  for (let i = 0; i + 1 < h.length; i += 2) out += String.fromCharCode(parseInt(h.substr(i, 2), 16));
  return out;
}
function parseCMap(text) {
  const map = new Map();
  let mm;
  const charRe = /beginbfchar([\s\S]*?)endbfchar/g;
  while ((mm = charRe.exec(text)) !== null) {
    const pairRe = /<([0-9a-fA-F]+)>\s*<([0-9a-fA-F]+)>/g;
    let p;
    while ((p = pairRe.exec(mm[1])) !== null) map.set(p[1].toLowerCase(), hexToStr(p[2]));
  }
  const rangeRe = /beginbfrange([\s\S]*?)endbfrange/g;
  while ((mm = rangeRe.exec(text)) !== null) {
    const itemRe = /<([0-9a-fA-F]+)>\s*<([0-9a-fA-F]+)>\s*(?:<([0-9a-fA-F]+)>|\[([\s\S]*?)\])/g;
    let p;
    while ((p = itemRe.exec(mm[1])) !== null) {
      const lo = parseInt(p[1], 16), hi = parseInt(p[2], 16), width = p[1].length;
      if (p[3]) {
        const base = parseInt(p[3], 16);
        for (let c = lo; c <= hi && c - lo < 2000; c++)
          map.set(c.toString(16).padStart(width, '0'), String.fromCodePoint(base + (c - lo)));
      } else if (p[4]) {
        const dests = p[4].match(/<([0-9a-fA-F]+)>/g) || [];
        for (let c = lo; c <= hi && c - lo < dests.length; c++)
          map.set(c.toString(16).padStart(width, '0'), hexToStr(dests[c - lo].slice(1, -1)));
      }
    }
  }
  return map;
}
const fontObjMaps = {};
function mapForFontObj(num) {
  if (fontObjMaps[num] !== undefined) return fontObjMaps[num];
  let map = new Map();
  const o = objs[num];
  if (o) {
    const tu = o.match(/\/ToUnicode\s+(\d+)\s+0\s+R/);
    if (tu) {
      const cm = objs[parseInt(tu[1])];
      const body = cm && streamBody(cm);
      if (body) map = parseCMap(body);
    }
  }
  fontObjMaps[num] = map;
  return map;
}

// ---------- matrix helpers ----------
function mul(A, B) {
  return [
    A[0]*B[0] + A[1]*B[2], A[0]*B[1] + A[1]*B[3],
    A[2]*B[0] + A[3]*B[2], A[2]*B[1] + A[3]*B[3],
    A[4]*B[0] + A[5]*B[2] + B[4], A[4]*B[1] + A[5]*B[3] + B[5],
  ];
}
const ID = [1, 0, 0, 1, 0, 0];

// ---------- extract glyphs ----------
function extract(content, fonts) {
  const glyphs = [];
  let ctm = ID.slice();
  const stack = [];
  let curMap = null, curSize = 12, tm = ID.slice();

  const tokRe = /\/[A-Za-z0-9]+\s+gs|\/[A-Za-z0-9]+\s+[\d.]+\s+Tf|-?[\d.]+(?:\s+-?[\d.]+){5}\s+Tm|-?[\d.]+(?:\s+-?[\d.]+){5}\s+cm|<[0-9a-fA-F]+>\s*Tj|\[[\s\S]*?\]\s*TJ|\bq\b|\bQ\b|-?[\d.]+\s+-?[\d.]+\s+(?:Td|TD)|T\*|\bBT\b|\bET\b/g;
  let t;
  while ((t = tokRe.exec(content)) !== null) {
    const tok = t[0];
    if (tok === 'q') stack.push(ctm.slice());
    else if (tok === 'Q') { if (stack.length) ctm = stack.pop(); }
    else if (tok.endsWith(' cm')) {
      const n = tok.match(/-?[\d.]+/g).map(Number);
      ctm = mul(ctm, n);
    } else if (tok.endsWith(' Tf')) {
      const mm2 = tok.match(/(\/[A-Za-z0-9]+)\s+([\d.]+)/);
      const name = mm2[1].slice(1);
      curMap = fonts[name] || null;
      curSize = parseFloat(mm2[2]);
    } else if (tok.endsWith(' Tm')) {
      const n = tok.match(/-?[\d.]+/g).map(Number);
      tm = n;
    } else if (/\sTj$/.test(tok)) {
      pushHex(tok.match(/<([0-9a-fA-F]+)>/)[1]);
    } else if (tok.startsWith('[')) {
      const partRe = /<([0-9a-fA-F]+)>|(-?[\d.]+)/g;
      let p;
      while ((p = partRe.exec(tok)) !== null) {
        if (p[1]) pushHex(p[1]);
        else {
          const n = parseFloat(p[2]);
          const x = ctm[0]*tm[4] + ctm[2]*tm[5] + ctm[4];
          if (glyphs.length && Math.abs(n) > 100 && glyphs[glyphs.length-1].line === undefined) {}
          // kerning shift: move last glyph's effective advance
          if (glyphs.length && Math.abs(n) > 150) glyphs[glyphs.length - 1].kern = (glyphs[glyphs.length-1].kern||0) + n/1000 * curSize;
        }
      }
    }
  }

  function pushHex(hex) {
    hex = hex.replace(/\s/g, '').toLowerCase();
    const scale = Math.hypot(tm[0], tm[1]) || 1;
    const eff = curSize * scale * Math.hypot(ctm[0], ctm[1]);
    const x = ctm[0]*tm[4] + ctm[2]*tm[5] + ctm[4];
    const y = ctm[1]*tm[4] + ctm[3]*tm[5] + ctm[5];
    let i = 0;
    let idx = 0;
    while (i < hex.length) {
      let ch = null, used = 2;
      for (const len of [4, 2, 1]) {
        if (i + len <= hex.length && curMap && curMap.has(hex.substr(i, len))) { ch = curMap.get(hex.substr(i, len)); used = len; break; }
      }
      if (ch === null) { used = Math.min(2, hex.length - i); ch = hexToStr(hex.substr(i, used)); }
      if (ch && ch.charCodeAt(0) > 31 && ch !== '\uFEFF') {
        glyphs.push({ x: x + idx * eff * 0.55, y, ch, eff });
      }
      i += used;
      idx++;
    }
    // advance text matrix horizontally for following glyphs in same Tj
    tm = [tm[0], tm[1], tm[2], tm[3], tm[4] + hex.length/2 * 0, tm[5]];
  }

  return glyphs;
}

// ---------- pages ----------
const pages = [];
for (const k of Object.keys(objs)) {
  if (/\/Type\s*\/Page\b/.test(objs[k]) && !/\/Type\s*\/Pages\b/.test(objs[k])) pages.push({ num: +k, o: objs[k] });
}
pages.sort((a, b) => a.num - b.num);

const out = [];
for (const page of pages) {
  const cr = page.o.match(/\/Contents\s+(\d+)\s+0\s+R/);
  if (!cr) continue;
  const body = streamBody(objs[cr[1]]);
  if (!body) continue;
  let resText = null;
  const rs = page.o.match(/\/Resources\s+(\d+)\s+0\s+R/);
  if (rs) resText = objs[rs[1]];
  else { const ri = page.o.match(/\/Resources\s*<<([\s\S]*?)>>/); if (ri) resText = '<<' + ri[1] + '>>'; }
  const fonts = {};
  if (resText) {
    let fm = resText.match(/\/Font\s*<<([\s\S]*?)>>/);
    if (!fm) { const fr = resText.match(/\/Font\s+(\d+)\s+0\s+R/); if (fr) fm = { 1: objs[fr[1]] }; }
    if (fm) {
      const pairRe = /(\/[A-Za-z0-9]+)\s+(\d+)\s+0\s+R/g;
      let p;
      while ((p = pairRe.exec(fm[1])) !== null) fonts[p[1].slice(1)] = mapForFontObj(parseInt(p[2]));
    }
  }

  const glyphs = extract(body, fonts);

  // group into lines
  glyphs.sort((a, b) => b.y - a.y || a.x - b.x);
  const lines = [];
  for (const g of glyphs) {
    const last = lines[lines.length - 1];
    if (last && Math.abs(g.y - last.y) <= Math.max(1.5, g.eff * 0.4)) {
      last.glyphs.push(g);
      last.y = (last.y * (last.glyphs.length - 1) + g.y) / last.glyphs.length;
    } else lines.push({ y: g.y, glyphs: [g] });
  }
  for (const line of lines) {
    line.glyphs.sort((a, b) => a.x - b.x);
    let s = '';
    let prev = null;
    for (const g of line.glyphs) {
      if (prev) {
        const gap = g.x - prev.x - prev.eff * 0.5 + (prev.kern || 0);
        if (gap > g.eff * 0.28) s += ' ';
      }
      s += g.ch;
      prev = g;
    }
    if (s.trim()) out.push(s.replace(/\s+$/, ''));
  }
  out.push('--- page break ---');
}
