function hexToStr(h) {
  h = h.replace(/\s/g, '');
  let out = '';
  for (let i = 0; i + 1 < h.length; i += 2) out += String.fromCharCode(parseInt(h.substr(i, 2), 16));
  return out;
}
// destinations in ToUnicode CMaps are UTF-16BE code units
function utf16beToStr(h) {
  h = h.replace(/\s/g, '');
  if (h.length % 4 !== 0) return hexToStr(h);
  let out = '';
  for (let i = 0; i + 3 < h.length; i += 4) out += String.fromCharCode(parseInt(h.substr(i, 4), 16));
  return out;
}

