package com.example.Used.Model;

import jakarta.persistence.*;
import lombok.Getter;
import lombok.NoArgsConstructor;
import lombok.Setter;
import org.hibernate.annotations.CreationTimestamp;
import org.hibernate.annotations.UpdateTimestamp;

import java.math.BigDecimal;
import java.time.LocalDateTime;

/**
 * Buyer/Seller balance used by the payment process.
 *
 * Concurrency notes (see PaymentProcess design):
 *  - Balance mutations are NEVER done as read-then-write in Java.
 *    They are atomic conditional UPDATE statements:
 *      UPDATE user_wallets SET balance = balance - :amt
 *      WHERE user_id = :uid AND balance >= :amt   -- rowcount 0 = insufficient funds
 *      UPDATE user_wallets SET balance = balance + :amt WHERE user_id = :uid
 *  - Workers additionally take a pessimistic (FOR UPDATE) lock on wallet rows,
 *    always in ascending user_id order, to prevent deadlocks when two payments
 *    move money in opposite directions between the same pair of users.
 */
@NoArgsConstructor
@Getter
@Setter
@Entity
@Table(name = "user_wallets")
public class Wallet {

    @Id
    @Column
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    /**
     * One wallet per user. The FK lives on THIS table (unique) instead of on
     * `users`, so the existing User entity and its save-flows stay untouched.
     */
    @ManyToOne(fetch = FetchType.LAZY)
    @JoinColumn(name = "user_id", nullable = false, unique = true)
    private User user;

    /**
     * BigDecimal, not double: floating point must never touch money.
     */
    @Column(nullable = false, precision = 12, scale = 2)
    private BigDecimal balance = BigDecimal.ZERO;

    @Column
    @CreationTimestamp
    private LocalDateTime createdAt;

    @Column
    @UpdateTimestamp
    private LocalDateTime updatedAt;

    public Wallet(User user) {
        this.user = user;
        this.balance = BigDecimal.ZERO;
    }
}

package com.example.Used.Model;

import jakarta.persistence.*;
import lombok.Getter;
import lombok.NoArgsConstructor;
import lombok.Setter;
import org.hibernate.annotations.CreationTimestamp;
import org.hibernate.annotations.UpdateTimestamp;

import java.math.BigDecimal;
import java.time.LocalDateTime;

/**
 * A single payment attempt for a listing. Source of truth for the money side
 * of a purchase; the {@link Transactions} row is written inside the same DB
 * transaction that completes the payment.
 *
 * State machine:
 *   PENDING -> PROCESSING -> COMPLETED
 *   PENDING/PROCESSING ---> FAILED (with failureReason)
 *   COMPLETED -----------> REFUNDED (future)
 */
@NoArgsConstructor
@Getter
@Setter
@Entity
@Table(name = "payments")
public class Payment {

    @Id
    @Column
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @ManyToOne(fetch = FetchType.LAZY)
    @JoinColumn(name = "listing_id", nullable = false)
    private Listings listing;

    @ManyToOne(fetch = FetchType.LAZY)
    @JoinColumn(name = "buyer_id", nullable = false)
    private User buyer;

    @ManyToOne(fetch = FetchType.LAZY)
    @JoinColumn(name = "seller_id", nullable = false)
    private User seller;

    @Column(nullable = false, precision = 12, scale = 2)
    private BigDecimal amount;

    public enum Status {
        PENDING,
        PROCESSING,
        COMPLETED,
        FAILED
    }

    @Enumerated(EnumType.STRING)
    @Column(nullable = false)
    private Status status;

    /** Set when status = FAILED, e.g. INSUFFICIENT_FUNDS / ALREADY_SOLD / SYSTEM_ERROR */
    @Column
    private String failureReason;

    /** When the worker finished (COMPLETED or FAILED) */
    @Column
    private LocalDateTime processedAt;

    @Column
    @CreationTimestamp
    private LocalDateTime createdAt;

    @Column
    @UpdateTimestamp
    private LocalDateTime updatedAt;
}

package com.example.Used.Repository;

import com.example.Used.Model.Wallet;
import jakarta.persistence.LockModeType;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Lock;
import org.springframework.data.jpa.repository.Modifying;
import org.springframework.data.jpa.repository.Query;
import org.springframework.data.repository.query.Param;
import org.springframework.stereotype.Repository;

import java.math.BigDecimal;
import java.util.Optional;

@Repository
public interface WalletRepository extends JpaRepository<Wallet, Long> {

    Optional<Wallet> findByUserId(Long userId);

    /**
     * Layer-3 defense (deadlock prevention): locks the wallet row FOR UPDATE
     * until the surrounding transaction commits or rolls back.
     * Callers MUST lock wallets in ascending user_id order.
     */
    @Lock(LockModeType.PESSIMISTIC_WRITE)
    @Query("SELECT w FROM Wallet w WHERE w.user.id = :userId")
    Optional<Wallet> findByIdForUpdate(@Param("userId") Long userId);

    /**
     * Layer-2 defense (balance race): check and debit in ONE statement.
     * Two threads can never both pass a balance check, because the check
     * happens inside the UPDATE itself on the locked row.
     *
     * Returns the number of rows updated: 0 = insufficient funds.
     *
     * NOTE: bulk JPQL updates bypass the Hibernate persistence context and do
     * NOT fire @UpdateTimestamp. The worker must not hold stale Wallet entities
     * in its session when calling this (re-read after, or flush+clear first).
     */
    @Modifying(clearAutomatically = true, flushAutomatically = true)
    @Query("UPDATE Wallet w SET w.balance = w.balance - :amount " +
           "WHERE w.user.id = :userId AND w.balance >= :amount")
    int debit(@Param("userId") Long userId, @Param("amount") BigDecimal amount);

    /** Atomic credit (counterpart of debit). Returns rows updated (0 = no wallet). */
    @Modifying(clearAutomatically = true, flushAutomatically = true)
    @Query("UPDATE Wallet w SET w.balance = w.balance + :amount " +
           "WHERE w.user.id = :userId")
    int credit(@Param("userId") Long userId, @Param("amount") BigDecimal amount);
}

package com.example.Used.Repository;

import com.example.Used.Model.Payment;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.stereotype.Repository;

import java.util.Collection;
import java.util.List;
import java.util.Optional;

@Repository
public interface PaymentRepository extends JpaRepository<Payment, Long> {

    /**
     * Layer-4 defense (double click / retry): finds any ACTIVE payment for a
     * listing. Combined with the partial unique index
     * (see db/payment-indexes.sql) the DATABASE itself refuses a second
     * concurrent payment for the same listing.
     */
    Optional<Payment> findFirstByListingIdAndStatusInOrderByIdDesc(
            Long listingId,
            Collection<Payment.Status> statuses
    );

    /** Idempotency for the buyer: "do I already have an active payment for this listing?" */
    Optional<Payment> findFirstByBuyerIdAndListingIdAndStatusInOrderByIdDesc(
            Long buyerId,
            Long listingId,
            Collection<Payment.Status> statuses
    );

    List<Payment> findByBuyerIdOrderByCreatedAtDesc(Long buyerId);

    List<Payment> findBySellerIdOrderByCreatedAtDesc(Long sellerId);
}

