package com.example.Used.Service;

import com.example.Used.Exceptions.ResourceNotFoundException;
import com.example.Used.Model.*;
import com.example.Used.Repository.*;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.stereotype.Service;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.TransactionDefinition;
import org.springframework.transaction.support.TransactionTemplate;

import java.time.LocalDateTime;
import java.util.Optional;

/**
 * Executes ONE payment, on a pool thread, inside ONE database transaction.
 *
 * IMPORTANT design note — why TransactionTemplate instead of @Transactional:
 *  1) This method is called from the payment pool. Putting @Transactional on a
 *     method that SELF-invokes its own transactional internals would be
 *     SILENTLY IGNORED (Spring proxies don't intercept internal calls).
 *     TransactionTemplate makes the transaction boundary explicit and visible.
 *  2) The state-changing work (mainTx) and the failure-marking (failureTx)
 *     must be SEPARATE transactions: when the payment rolls back, marking it
 *     FAILED must NOT roll back with it — it needs REQUIRES_NEW.
 *  3) Side effects (audit/email/SSE) run AFTER mainTx commits, so a
 *     rolled-back payment can never notify anyone.
 */
@Service
public class PaymentWorker {

    private static final Logger log = LoggerFactory.getLogger(PaymentWorker.class);

    private final TransactionTemplate mainTx;
    private final TransactionTemplate failureTx;

    private final PaymentRepository paymentRepository;
    private final ListingRepository listingRepository;
    private final WalletRepository walletRepository;
    private final TransactionsRepository transactionsRepository;
    private final UserRepository userRepository;
    private final AuditLogService auditLogService;
    private final EmailServices emailServices;
    private final NotificationService notificationService;

    public PaymentWorker(PaymentRepository paymentRepository,
                         ListingRepository listingRepository,
                         WalletRepository walletRepository,
                         TransactionsRepository transactionsRepository,
                         UserRepository userRepository,
                         AuditLogService auditLogService,
                         EmailServices emailServices,
                         NotificationService notificationService,
                         PlatformTransactionManager txManager) {
        this.paymentRepository = paymentRepository;
        this.listingRepository = listingRepository;
        this.walletRepository = walletRepository;
        this.transactionsRepository = transactionsRepository;
        this.userRepository = userRepository;
        this.auditLogService = auditLogService;
        this.emailServices = emailServices;
        this.notificationService = notificationService;

        this.mainTx = new TransactionTemplate(txManager); // PROPAGATION_REQUIRED

        this.failureTx = new TransactionTemplate(txManager);
        this.failureTx.setPropagationBehavior(TransactionDefinition.PROPAGATION_REQUIRES_NEW);
    }

    /** Entry point for the pool thread. NO @Transactional here — see class javadoc. */
    public void processPayment(Long paymentId) {
        log.info("[PAYMENT] #{} processing on thread '{}'", paymentId, Thread.currentThread().getName());
        try {
            mainTx.executeWithoutResult(status -> executePayment(paymentId));
        } catch (PaymentFailedException e) {
            log.info("[PAYMENT] #{} FAILED ({})", paymentId, e.getReason());
            markFailed(paymentId, e.getReason());
            return; // no success side effects
        } catch (Exception e) {
            log.error("[PAYMENT] #{} SYSTEM_ERROR", paymentId, e);
            markFailed(paymentId, "SYSTEM_ERROR");
            return;
        }
        onSuccess(paymentId); // runs only after a real DB commit
    }

    private void executePayment(Long paymentId) {
        Payment payment = paymentRepository.findById(paymentId)
                .orElseThrow(() -> new PaymentFailedException("PAYMENT_NOT_FOUND"));

        payment.setStatus(Payment.Status.PROCESSING);
        paymentRepository.save(payment);

        // ---- Layer 1: atomic listing claim (the double-sell defense) ----
        // ONE statement: the DB decides the winner, no check-then-act window.
        int claimed = listingRepository.updateStatusIfCurrent(
                payment.getListing().getId(),
                Listings.Status.ACTIVE,
                Listings.Status.SOLD);
        if (claimed == 0) {
            throw new PaymentFailedException("ALREADY_SOLD");
        }

        // ---- Layer 3: pessimistic wallet locks, ascending user_id ----
        // Both wallets are locked FOR UPDATE. Order matters: if buyer and
        // seller ids were locked in arbitrary order, two opposite-direction
        // payments could deadlock and Postgres would kill one.
        Long buyerId = payment.getBuyer().getId();
        Long sellerId = payment.getSeller().getId();
        if (buyerId <= sellerId) {
            walletRepository.findByIdForUpdate(buyerId);
            walletRepository.findByIdForUpdate(sellerId);
        } else {
            walletRepository.findByIdForUpdate(sellerId);
            walletRepository.findByIdForUpdate(buyerId);
        }

        // ---- Layer 2: atomic check-and-debit (the balance race defense) ----
        // Balance is checked INSIDE the UPDATE — two of the buyer's concurrent
        // payments can never both succeed past the balance.
        int debited = walletRepository.debit(buyerId, payment.getAmount());
        if (debited == 0) {
            throw new PaymentFailedException("INSUFFICIENT_FUNDS");
        }

        int credited = walletRepository.credit(sellerId, payment.getAmount());
        if (credited == 0) {
            throw new PaymentFailedException("WALLET_MISSING"); // defensive; wallets are ensured at submit
        }

        // ---- Bookkeeping row, same transaction as everything above ----
        Transactions transaction = new Transactions();
        transaction.setListing(payment.getListing());
        transaction.setBuyer(payment.getBuyer());
        transaction.setSeller(payment.getSeller());
        transaction.setAmount(payment.getAmount());
        transaction.setStatus(Transactions.Status.COMPLETED);
        transactionsRepository.save(transaction);

        payment.setStatus(Payment.Status.COMPLETED);
        payment.setProcessedAt(LocalDateTime.now());
        paymentRepository.save(payment);
    }

    /** Separate REQUIRES_NEW transaction: survives the rollback above. */
    private void markFailed(Long paymentId, String reason) {
        try {
            failureTx.executeWithoutResult(status -> {
                paymentRepository.findById(paymentId).ifPresent(payment -> {
                    payment.setStatus(Payment.Status.FAILED);
                    payment.setFailureReason(reason);
                    payment.setProcessedAt(LocalDateTime.now());
                    paymentRepository.save(payment);
                });
            });
        } catch (Exception e) {
            log.error("[PAYMENT] #{} could not even be marked FAILED", paymentId, e);
        }
    }

    /** Audit + email + SSE — only ever reached after a real commit. */
    private void onSuccess(Long paymentId) {
        paymentRepository.findById(paymentId).ifPresent(payment -> {
            User buyer = userRepository.findById(payment.getBuyer().getId()).orElse(null);
            User seller = userRepository.findById(payment.getSeller().getId()).orElse(null);
            Listings listing = listingRepository.findById(payment.getListing().getId()).orElse(null);

            auditLogService.log(
                    AuditLog.AuditAction.LISTING_SOLD,
                    buyer,
                    "Listing '" + (listing != null ? listing.getTitle() : "?") + "' (id=" + payment.getListing().getId()
                            + ") sold for " + payment.getAmount() + " to user id=" + payment.getBuyer().getId(),
                    payment.getSeller().getId());

            if (seller != null && listing != null) {
                emailServices.sendListingSoldEmail(seller.getEmail(), listing.getTitle());
            }

            notificationService.sendToUser(payment.getSeller().getId(), "PAYMENT_COMPLETED", java.util.Map.of(
                    "paymentId", payment.getId(),
                    "listingId", payment.getListing().getId(),
                    "amount", payment.getAmount().toPlainString(),
                    "message", "Your item '" + (listing != null ? listing.getTitle() : "listing") + "' was sold!"));
        });
    }

    /** Carries the machine-readable failure reason (INSUFFICIENT_FUNDS, ALREADY_SOLD, ...). */
    static class PaymentFailedException extends RuntimeException {
        private final String reason;
        PaymentFailedException(String reason) { super(reason); this.reason = reason; }
        String getReason() { return reason; }
    }
}
```

