477:             if (!res.ok) throw new Error(`HTTP error! status: ${res.status}`);
478: 
479:             const activities = await res.json();
480:             renderActivityTimeline(activities, container);
481: 
482:         } catch (err) {
483:             console.error("Failed to load activity:", err);
484:             container.innerHTML = '<p class="empty-msg">Could not load recent activity.</p>';
485:         }
486:     }
