512:                         <p>${escapeHtml(item.details || 'System Event')}</p>
513:                         <span class="activity-time">${timeStr}</span>
514:                     </div>
515:                 </div>
516:             `;
517:             container.insertAdjacentHTML('beforeend', html);
518:         });
519:     }
