571:     // --- IMAGE UPLOAD LOGIC ---
572:     async function handleImageUpload(inputElement) {
573:         const file = inputElement.files[0];
574:         if (!file) return;
575: 
576:         const token = localStorage.getItem(TOKEN_KEY);
577:         if (!token) {
578:             alert("Session expired.");
579:             window.location.href = '/login';
580:             return;
581:         }
582: 
583:         // Show loading state on button/icon
584:         const overlay = document.querySelector('.upload-overlay');
585:         const originalHtml = overlay.innerHTML;
586:         overlay.innerHTML = '<i class="fas fa-spinner fa-spin"></i>';
587: 
588:         const formData = new FormData();
589:         formData.append('img', file);
590: 
591:         try {
592:             const res = await fetch('/api/profile/image', {
593:                 method: 'PUT',
594:                 headers: {
595:                     'Authorization': 'Bearer ' + token
596:                 },
597:                 body: formData
598:             });
599: 
600:             if (!res.ok) {
601:                 const errText = await res.text();
602:                 throw new Error(errText || "Upload failed");
603:             }
604: 
605:             const updatedData = await res.json();
606: 
607:             // Immediately update UI with new image
608:             if (updatedData.img && typeof updatedData.img === 'string') {
609:                  const mimeType = updatedData.imgtype || 'image/jpeg';
610:                  const avatarImg = document.getElementById('avatarImg');
611:                  const defaultIcon = document.querySelector('#avatarDisplay i');
