package com.example.Used.Service;

import com.example.Used.Exceptions.InformationExistException;
import com.example.Used.Model.User;
import com.example.Used.Model.Wallet;
import com.example.Used.Model.Responses.WalletStatus;
import com.example.Used.Repository.WalletRepository;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.math.BigDecimal;

@Service
public class WalletService {

    private static final BigDecimal MAX_AMOUNT = new BigDecimal("100000");

    private final WalletRepository walletRepository;
    private final CurrentUserService currentUserService;

    public WalletService(WalletRepository walletRepository, CurrentUserService currentUserService) {
        this.walletRepository = walletRepository;
        this.currentUserService = currentUserService;
    }

    public WalletStatus getWallet() {
        User user = currentUserService.getCurrentUser();
        ensureWallet(user);
        return WalletStatus.from(walletRepository.findByUserId(user.getId()).orElseThrow());
    }

    @Transactional
    public WalletStatus deposit(BigDecimal amount) {
        User user = currentUserService.getCurrentUser();
        checkAmount(amount);
        ensureWallet(user);
        walletRepository.credit(user.getId(), amount);   // atomic UPDATE
        return WalletStatus.from(walletRepository.findByUserId(user.getId()).orElseThrow());
    }

    @Transactional
    public WalletStatus withdraw(BigDecimal amount) {
        User user = currentUserService.getCurrentUser();
        checkAmount(amount);
        ensureWallet(user);
        if (walletRepository.debit(user.getId(), amount) == 0) {   // check + debit in one statement
            throw new InformationExistException("Not enough money in your wallet");
        }
        return WalletStatus.from(walletRepository.findByUserId(user.getId()).orElseThrow());
    }

    private void ensureWallet(User user) {
        walletRepository.createIfMissing(user.getId());
    }

    private void checkAmount(BigDecimal amount) {
        if (amount == null || amount.signum() <= 0) {
            throw new InformationExistException("Enter an amount greater than zero");
        }
        if (amount.compareTo(MAX_AMOUNT) > 0) {
            throw new InformationExistException("Maximum wallet transaction is 100,000");
        }
        if (amount.stripTrailingZeros().scale() > 2) {
            throw new InformationExistException("Amount can have at most 2 decimals");
        }
    }
}
```

