            payment.setFailureReason("ALREADY_SOLD");
            payment.setProcessedAt(LocalDateTime.now());
            paymentRepository.save(payment);
        } else {
            Transactions transaction = new Transactions();
            transaction.setListing(listing);
            transaction.setBuyer(payment.getBuyer());
            transaction.setSeller(payment.getSeller());
            transaction.setAmount(payment.getAmount().doubleValue());
            transaction.setStatus(Transactions.Status.COMPLETED);
            transactionsRepository.save(transaction);

            payment.setStatus(Payment.Status.COMPLETED);
            payment.setProcessedAt(LocalDateTime.now());
            paymentRepository.save(payment);
        }
        return PaymentStatus.from(payment);
    }

    @Transactional
    public PaymentStatus declineCod(Long paymentId) {
        Payment payment = loadCodForCurrentSeller(paymentId);
        payment.setStatus(Payment.Status.FAILED);
        payment.setFailureReason("COD_DECLINED");
        payment.setProcessedAt(LocalDateTime.now());
        paymentRepository.save(payment);
        return PaymentStatus.from(payment);
    }

    private Payment loadCodForCurrentSeller(Long paymentId) {
        User seller = currentUserService.getCurrentUser();
        Payment payment = paymentRepository.findById(paymentId)
                .orElseThrow(() -> new ResourceNotFoundException("Payment not found"));

        if (!payment.getSeller().getId().equals(seller.getId())) {
            throw new InformationExistException("Only the seller can respond to this request");
        }
        if (payment.getMethod() != Payment.Method.COD || payment.getStatus() != Payment.Status.PENDING) {
            throw new InformationExistException("This request has already been handled");
        }
        return payment;
    }

    /** Called by the controller AFTER the decision transaction commits. */
    public void notifyCodDecision(Long paymentId) {
        Payment payment = paymentRepository.findById(paymentId).orElse(null);
        if (payment == null) return;

        boolean accepted = payment.getStatus() == Payment.Status.COMPLETED;
        try {
            emailServices.sendCodDecisionEmail(
                    payment.getBuyer().getEmail(),
                    payment.getListing().getTitle(),
                    accepted);
        } catch (Exception e) {
            log.error("[COD] decision email failed for payment #{}", paymentId, e);
        }
        try {
            notificationService.sendToUser(payment.getBuyer().getId(), "NOTIFICATION", Map.of(
                    "title", accepted ? "Cash on delivery accepted" : "Cash on delivery declined",
                    "message", accepted
                            ? "The seller accepted your request for '" + payment.getListing().getTitle() + "'."
                            : "The seller declined your request for '" + payment.getListing().getTitle() + "'.",
                    "type", accepted ? "success" : "error"));
        } catch (Exception e) {
            log.error("[COD] decision notification failed for payment #{}", paymentId, e);
        }
    }
