24: /**
25:  * Accepts a purchase, records it as PENDING and hands the risky work to the
26:  * payment thread pool. This class NEVER locks rows or moves money itself —
27:  * it must stay fast and never block the HTTP request thread.
28:  */
29: @Service
30: public class PaymentService {
31: 
32:     private static final Logger log = LoggerFactory.getLogger(PaymentService.class);
33: 
34:     private static final List<Payment.Status> ACTIVE =
35:             List.of(Payment.Status.PENDING, Payment.Status.PROCESSING);
36: 
37:     private final PaymentRepository paymentRepository;
38:     private final ListingRepository listingRepository;
39:     private final WalletRepository walletRepository;
40:     private final CurrentUserService currentUserService;
41:     private final Executor paymentExecutor;   // the pool from Step 3
42:     private final PaymentWorker paymentWorker;
43: 
44:     public PaymentService(PaymentRepository paymentRepository,
45:                           ListingRepository listingRepository,
46:                           WalletRepository walletRepository,
47:                           CurrentUserService currentUserService,
48:                           @Qualifier("paymentExecutor") Executor paymentExecutor,
49:                           PaymentWorker paymentWorker) {
50:         this.paymentRepository = paymentRepository;
51:         this.listingRepository = listingRepository;
52:         this.walletRepository = walletRepository;
53:         this.currentUserService = currentUserService;
54:         this.paymentExecutor = paymentExecutor;
55:         this.paymentWorker = paymentWorker;
56:     }
57: 
58:     public PaymentResult submitPayment(Long listingId) {
59:         User buyer = currentUserService.getCurrentUser();
60: 
61:         if (buyer.getRole() == User.Role.ADMIN) {
62:             throw new InformationExistException("Admins cannot buy listings");
63:         }
64: 
65:         Listings listing = listingRepository.findById(listingId)
66:                 .orElseThrow(() -> new ResourceNotFoundException("Listing not found"));
67: 
68:         if (listing.getUser().getId().equals(buyer.getId())) {
69:             throw new InformationExistException("You cannot buy your own listing");
70:         }
71:         if (listing.getStatus() != Listings.Status.ACTIVE) {
72:             throw new InformationExistException("Listing is no longer available for purchase");
73:         }
74: 
75:         // Idempotency: a double-click or retried request gets the SAME payment back
76:         Optional<Payment> active =
77:                 paymentRepository.findFirstByBuyerIdAndListingIdAndStatusInOrderByIdDesc(
78:                         buyer.getId(), listingId, ACTIVE);
79:         if (active.isPresent()) {
80:             return PaymentResult.duplicate(active.get());
81:         }
82: 
83:         User seller = listing.getUser();
84: 
85:         // Wallets must exist before the worker runs (creating them inside two
86:         // racing workers could hit the unique user_id constraint)
87:         ensureWallet(buyer);
88:         ensureWallet(seller);
89: 
90:         Payment payment = new Payment();
91:         payment.setListing(listing);
92:         payment.setBuyer(buyer);
93:         payment.setSeller(seller);
94:         payment.setAmount(java.math.BigDecimal.valueOf(listing.getPrice())); // price is legacy double
95:         payment.setStatus(Payment.Status.PENDING);
96:         Payment saved = paymentRepository.save(payment); // unique index backstops races
97: 
98:         try {
99:             paymentExecutor.execute(() -> {
100:                 try {
101:                     paymentWorker.executePayment(saved.getId());
102:                 } catch (PaymentWorker.PaymentFailedException e) {
103:                     log.info("[PAYMENT] #{} failed: {}", saved.getId(), e.getReason());
104:                     paymentWorker.markFailed(saved.getId(), e.getReason());
105:                     return;
106:                 } catch (Exception e) {
107:                     log.error("[PAYMENT] #{} system error", saved.getId(), e);
108:                     paymentWorker.markFailed(saved.getId(), "SYSTEM_ERROR");
109:                     return;
110:                 }
111:                 // Payment committed. Side effects must never be able to mark
112:                 // a COMPLETED payment as FAILED, so they get their own try/catch.
113:                 try {
114:                     paymentWorker.onPaymentCompleted(saved.getId());
115:                 } catch (Exception e) {
116:                     log.error("[PAYMENT] #{} completed, but post-commit side effects failed", saved.getId(), e);
117:                 }
118:             });
119:         } catch (RejectedExecutionException e) {
120:             // Queue full — the pool is protecting the database
121:             saved.setStatus(Payment.Status.FAILED);
122:             saved.setFailureReason("QUEUE_FULL");
123:             paymentRepository.save(saved);
124:             throw new RateLimitException("Marketplace is busy processing payments - please try again");
125:         }
126: 
127:         log.info("[PAYMENT] #{} accepted (listing={}, buyer={})",
128:                 saved.getId(), listingId, buyer.getId());
129:         return PaymentResult.accepted(saved);
130:     }
131: 
132:     public Payment getPayment(Long id) {
133:         return paymentRepository.findById(id)
134:                 .orElseThrow(() -> new ResourceNotFoundException("Payment not found"));
135:     }
136: 
137:     private void ensureWallet(User user) {
138:         if (walletRepository.findByUserId(user.getId()).isEmpty()) {
139:             walletRepository.save(new Wallet(user));
140:         }
141:     }
142: }

