52:     /** All the money work in ONE transaction. Throws => everything rolls back. */
53:     @Transactional
54:     public void executePayment(Long paymentId) {
55:         log.info("[PAYMENT] #{} running on '{}'", paymentId, Thread.currentThread().getName());
56: 
57:         Payment payment = paymentRepository.findById(paymentId)
58:                 .orElseThrow(() -> new PaymentFailedException("PAYMENT_NOT_FOUND"));
59: 
60:         payment.setStatus(Payment.Status.PROCESSING);
61:         paymentRepository.save(payment);
62: 
63:         // Defense 1: only one buyer wins the ACTIVE -> SOLD flip
64:         int claimed = listingRepository.updateStatusIfCurrent(
65:                 payment.getListing().getId(), Listings.Status.ACTIVE, Listings.Status.SOLD);
66:         if (claimed == 0) {
67:             throw new PaymentFailedException("ALREADY_SOLD");
68:         }
69: 
70:         // Defense 3: lock both wallets, always lowest id first (no deadlocks)
71:         Long buyerId = payment.getBuyer().getId();
72:         Long sellerId = payment.getSeller().getId();
73:         if (buyerId <= sellerId) {
74:             walletRepository.findByIdForUpdate(buyerId);
75:             walletRepository.findByIdForUpdate(sellerId);
76:         } else {
77:             walletRepository.findByIdForUpdate(sellerId);
78:             walletRepository.findByIdForUpdate(buyerId);
79:         }
80: 
81:         // Defense 2: the balance check lives INSIDE the update
82:         if (walletRepository.debit(buyerId, payment.getAmount()) == 0) {
83:             throw new PaymentFailedException("INSUFFICIENT_FUNDS");
84:         }
85:         if (walletRepository.credit(sellerId, payment.getAmount()) == 0) {
86:             throw new PaymentFailedException("WALLET_MISSING");
87:         }
