89:         Transactions transaction = new Transactions();
90:         transaction.setListing(payment.getListing());
91:         transaction.setBuyer(payment.getBuyer());
92:         transaction.setSeller(payment.getSeller());
93:         transaction.setAmount(payment.getAmount().doubleValue()); // legacy Transactions.amount is double
94:         transaction.setStatus(Transactions.Status.COMPLETED);
95:         transactionsRepository.save(transaction);
96: 
97:         payment.setStatus(Payment.Status.COMPLETED);
98:         payment.setProcessedAt(LocalDateTime.now());
99:         paymentRepository.save(payment);
100:     }
