105:             User buyer = userRepository.findById(payment.getBuyer().getId()).orElse(null);
106:             User seller = userRepository.findById(payment.getSeller().getId()).orElse(null);
107:             Listings listing = listingRepository.findById(payment.getListing().getId()).orElse(null);
108:             String title = (listing != null) ? listing.getTitle() : "listing";
109: 
110:             auditLogService.log(
111:                     AuditLog.AuditAction.LISTING_SOLD,
112:                     buyer,
113:                     "Listing '" + title + "' (id=" + payment.getListing().getId()
114:                             + ") sold for " + payment.getAmount(),
115:                     payment.getSeller().getId());
116: 
117:             if (seller != null && listing != null) {
118:                 emailServices.sendListingSoldEmail(seller.getEmail(), title);
119:             }
120: 
121:             notificationService.sendToUser(payment.getSeller().getId(), "PAYMENT_COMPLETED", Map.of(
122:                     "paymentId", payment.getId(),
123:                     "listingId", payment.getListing().getId(),
124:                     "amount", payment.getAmount().toPlainString(),
