404:             if (!res.ok) throw new Error('Failed to load profile');
405: 
406:             const data = await res.json();
407: 
408:             // Store User ID for reference
409:             if(data.user && data.user.id) {
410:                 currentUserId = data.user.id;
411:             } else if (data.id) {
412:                 currentUserId = data.id;
413:             }
414: 
415:             renderProfile(data);
416: 
417:             // 2. Fetch Activity History
418:             loadUserActivity(token);
419: 
420:         } catch (err) {
421:             console.error(err);
422:             alert("Could not load profile. Please log in again.");
423:             window.location.href = '/login';
