436:         document.getElementById('displayName').textContent = fullName;
437:         document.getElementById('displayEmail').textContent = data.email || 'N/A';
438: 
439:         if(data.createdAt) {
440:             const date = new Date(data.createdAt);
441:             document.getElementById('displayJoined').textContent = date.toLocaleDateString();
442:         } else {
443:             document.getElementById('displayJoined').textContent = "Today";
444:         }
445: 
446:         // Handle Image Display
447:         const avatarImg = document.getElementById('avatarImg');
448:         const defaultIcon = document.querySelector('#avatarDisplay i');
449: 
450:         if (data.img && typeof data.img === 'string' && data.img.length > 0) {
451:             const mimeType = data.imgtype || 'image/jpeg';
452:             avatarImg.src = `data:${mimeType};base64,${data.img}`;
453:             avatarImg.style.display = 'block';
454:             if(defaultIcon) defaultIcon.style.display = 'none';
455:         } else {
456:             avatarImg.style.display = 'none';
457:             if(defaultIcon) defaultIcon.style.display = 'flex';
458:         }
