499:             const timeStr = dateObj.toLocaleString(undefined, {
500:                 month: 'short', day: 'numeric', hour: '2-digit', minute:'2-digit'
501:             });
502: 
503:             // Map Action Enum to Readable Text
504:             let actionText = item.action ? item.action.replace('_', ' ').toLowerCase() : 'Event';
505:             actionText = actionText.charAt(0).toUpperCase() + actionText.slice(1);
506: 
