async function handlePurchase() {
    // 1. Auth Check
    const token = localStorage.getItem(TOKEN_KEY);
    if (!token) {
        alert("Please log in to purchase items.");
        window.location.href = '/login';
        return;
    }

    // 2. Confirmation
    if (!confirm(`Are you sure you want to buy "${listingData.title}" for $${listingData.price}?`)) {
        return;
    }

    const btn = document.getElementById('buyBtn');
    const originalHtml = btn.innerHTML;
    btn.disabled = true;
    btn.innerHTML = '<i class="fas fa-spinner fa-spin"></i> Processing...';

    try {
        // 3. Call API: POST /api/listings/{id}/buy
        const res = await fetch(`/api/listings/${currentListingId}/buy`, {
            method: 'POST',
            headers: {
                'Authorization': 'Bearer ' + token,
                'Content-Type': 'application/json'
            }
        });

        if (res.ok) {
            // Success
            alert("Purchase successful! The item has been marked as SOLD.");
            // Reload page to update status to SOLD immediately
            window.location.reload();
        } else {
            // Handle specific errors from backend (e.g., "Already sold", "Insufficient funds")
            const errText = await res.text();
            throw new Error(errText || "Purchase failed.");
        }

    } catch (err) {
        console.error(err);
        alert("Error: " + err.message);
        btn.disabled = false;
        btn.innerHTML = originalHtml;
    }
}

