27: /**
28:  * Accepts a purchase, records it as PENDING and hands the risky work to the
29:  * payment thread pool. This class NEVER locks rows or moves money itself —
30:  * it must stay fast and never block the HTTP request thread.
31:  *
32:  * Cash on delivery is different: the payment waits in PENDING until the
33:  * seller accepts or declines, so it is not sent to the pool.
34:  */
35: @Service
36: public class PaymentService {
37: 
38:     private static final Logger log = LoggerFactory.getLogger(PaymentService.class);
39: 
40:     private static final List<Payment.Status> ACTIVE =
41:             List.of(Payment.Status.PENDING, Payment.Status.PROCESSING);
42: 
43:     private final PaymentRepository paymentRepository;
44:     private final ListingRepository listingRepository;
45:     private final WalletService walletService;
46:     private final CurrentUserService currentUserService;
47:     private final Executor paymentExecutor;   // the pool from Step 3
48:     private final PaymentWorker paymentWorker;
49:     private final EmailServices emailServices;
50:     private final NotificationService notificationService;
51: 
52:     public PaymentService(PaymentRepository paymentRepository,
53:                           ListingRepository listingRepository,
54:                           WalletService walletService,
55:                           CurrentUserService currentUserService,
56:                           @Qualifier("paymentExecutor") Executor paymentExecutor,
57:                           PaymentWorker paymentWorker,
58:                           EmailServices emailServices,
59:                           NotificationService notificationService) {
60:         this.paymentRepository = paymentRepository;
61:         this.listingRepository = listingRepository;
62:         this.walletService = walletService;
63:         this.currentUserService = currentUserService;
64:         this.paymentExecutor = paymentExecutor;
65:         this.paymentWorker = paymentWorker;
66:         this.emailServices = emailServices;
67:         this.notificationService = notificationService;
68:     }
69: 
70:     public PaymentResult submitPayment(Long listingId, Payment.Method method) {
71:         Payment.Method chosen = (method == null) ? Payment.Method.WALLET : method;
72: 
73:         User buyer = currentUserService.getCurrentUser();
74: 
75:         if (buyer.getRole() == User.Role.ADMIN) {
76:             throw new InformationExistException("Admins cannot buy listings");
77:         }
78:         if (chosen == Payment.Method.CARD) {
79:             throw new InformationExistException(
80:                     "Card payments are coming soon. Please use your wallet or cash on delivery.");
81:         }
82: 
83:         Listings listing = listingRepository.findById(listingId)
84:                 .orElseThrow(() -> new ResourceNotFoundException("Listing not found"));
85: 
86:         if (listing.getUser().getId().equals(buyer.getId())) {
87:             throw new InformationExistException("You cannot buy your own listing");
88:         }
89:         if (listing.getStatus() != Listings.Status.ACTIVE) {
90:             throw new InformationExistException("Listing is no longer available for purchase");
91:         }
92: 
93:         // Idempotency: a double-click gets the SAME payment back
94:         Optional<Payment> sameBuyerActive =
95:                 paymentRepository.findFirstByBuyerIdAndListingIdAndStatusInOrderByIdDesc(
96:                         buyer.getId(), listingId, ACTIVE);
97:         if (sameBuyerActive.isPresent()) {
98:             return PaymentResult.duplicate(sameBuyerActive.get());
99:         }
100: 
101:         // One active payment per listing (the partial unique index is the
102:         // final backstop). Check first so the caller gets a clear message.
103:         Optional<Payment> anyActive =
104:                 paymentRepository.findFirstByListingIdAndStatusInOrderByIdDesc(listingId, ACTIVE);
105:         if (anyActive.isPresent()) {
106:             Payment existing = anyActive.get();
107:             if (existing.getBuyer().getId().equals(buyer.getId())) {
108:                 return PaymentResult.duplicate(existing);
109:             }
110:             throw new InformationExistException(existing.getMethod() == Payment.Method.COD
111:                     ? "This item is reserved for another buyer's cash-on-delivery request"
112:                     : "This item is already being purchased by another buyer");
113:         }
114: 
115:         User seller = listing.getUser();
116: 
117:         // Wallets must exist before the worker runs. COD moves no money, so
118:         // it does not need them at all.
119:         if (chosen == Payment.Method.WALLET) {
120:             walletService.ensureWallet(buyer.getId());
121:             walletService.ensureWallet(seller.getId());
122:         }
123: 
124:         Payment payment = new Payment();
125:         payment.setListing(listing);
126:         payment.setBuyer(buyer);
127:         payment.setSeller(seller);
128:         payment.setMethod(chosen);
129:         payment.setAmount(BigDecimal.valueOf(listing.getPrice())); // price is legacy double
130:         payment.setStatus(Payment.Status.PENDING);
131: 
132:         Payment saved;
133:         try {
134:             saved = paymentRepository.save(payment); // unique index backstops races
135:         } catch (DataIntegrityViolationException e) {
136:             throw new InformationExistException("This item is already being purchased by another buyer");
137:         }
138: 
139:         if (chosen == Payment.Method.COD) {
140:             notifyCodRequest(saved);
141:             log.info("[COD] #{} request (listing={}, buyer={}, seller={})",
142:                     saved.getId(), listingId, buyer.getId(), seller.getId());
143:             return PaymentResult.accepted(saved);
144:         }
145: 
146:         submitToPool(saved);
147: 
148:         log.info("[PAYMENT] #{} accepted (listing={}, buyer={})",
149:                 saved.getId(), listingId, buyer.getId());
150:         return PaymentResult.accepted(saved);
151:     }
152: 
153:     private void submitToPool(Payment saved) {
154:         try {
155:             paymentExecutor.execute(() -> {
156:                 try {
157:                     paymentWorker.executePayment(saved.getId());
158:                 } catch (PaymentWorker.PaymentFailedException e) {
159:                     log.info("[PAYMENT] #{} failed: {}", saved.getId(), e.getReason());
160:                     paymentWorker.markFailed(saved.getId(), e.getReason());
161:                     return;
162:                 } catch (Exception e) {
163:                     log.error("[PAYMENT] #{} system error", saved.getId(), e);
164:                     paymentWorker.markFailed(saved.getId(), "SYSTEM_ERROR");
165:                     return;
166:                 }
167:                 // Payment committed. Side effects must never be able to mark
168:                 // a COMPLETED payment as FAILED, so they get their own try/catch.
169:                 try {
170:                     paymentWorker.onPaymentCompleted(saved.getId());
171:                 } catch (Exception e) {
172:                     log.error("[PAYMENT] #{} completed, but post-commit side effects failed", saved.getId(), e);
173:                 }
174:             });
175:         } catch (RejectedExecutionException e) {
176:             // Queue full — the pool is protecting the database
177:             paymentWorker.markFailed(saved.getId(), "QUEUE_FULL");
178:             throw new RateLimitException("Marketplace is busy processing payments - please try again");
179:         }
180:     }
