182:     public Payment getPayment(Long id) {
183:         return paymentRepository.findById(id)
184:                 .orElseThrow(() -> new ResourceNotFoundException("Payment not found"));
185:     }
186: 
187:     /** Seller accepted a COD request: claim the listing, notify the buyer. */
188:     public PaymentStatus acceptCod(Long paymentId) {
189:         User seller = currentUserService.getCurrentUser();
190:         requireCodPaymentForSeller(paymentId, seller);
191: 
192:         try {
193:             paymentWorker.acceptCodPayment(paymentId, seller.getId());
194:         } catch (PaymentWorker.PaymentFailedException e) {
195:             handleCodFailure(paymentId, e.getReason());
196:             throw new InformationExistException(codErrorMessage(e.getReason()));
197:         }
198: 
199:         notifyCodDecision(paymentId, true);
200:         return PaymentStatus.from(getPayment(paymentId));
201:     }
202: 
203:     /** Seller declined a COD request: close the payment, notify the buyer. */
204:     public PaymentStatus declineCod(Long paymentId) {
205:         User seller = currentUserService.getCurrentUser();
206:         requireCodPaymentForSeller(paymentId, seller);
207: 
208:         try {
209:             paymentWorker.declineCodPayment(paymentId, seller.getId());
210:         } catch (PaymentWorker.PaymentFailedException e) {
211:             handleCodFailure(paymentId, e.getReason());
212:             throw new InformationExistException(codErrorMessage(e.getReason()));
213:         }
214: 
215:         notifyCodDecision(paymentId, false);
216:         return PaymentStatus.from(getPayment(paymentId));
217:     }
218: 
219:     /** Requests waiting for the current seller to accept or decline. */
220:     public List<CodRequestStatus> getPendingCodRequests() {
221:         User seller = currentUserService.getCurrentUser();
222:         return paymentRepository
223:                 .findBySellerIdAndMethodAndStatusOrderByCreatedAtDesc(
224:                         seller.getId(), Payment.Method.COD, Payment.Status.PENDING)
225:                 .stream()
226:                 .map(CodRequestStatus::from)
227:                 .toList();
228:     }
229: 
230:     private void requireCodPaymentForSeller(Long paymentId, User seller) {
231:         Payment payment = getPayment(paymentId);
232:         if (!payment.getSeller().getId().equals(seller.getId())) {
233:             throw new ResourceNotFoundException("Payment not found");
234:         }
235:         if (payment.getMethod() != Payment.Method.COD) {
236:             throw new InformationExistException("This payment is not a cash-on-delivery request");
237:         }
238:     }
239: 
240:     private void handleCodFailure(Long paymentId, String reason) {
241:         // ALREADY_HANDLED means another tab/click finished it: never overwrite
242:         // that outcome. ALREADY_SOLD and system errors close this request.
243:         if (!"ALREADY_HANDLED".equals(reason) && !"PAYMENT_NOT_FOUND".equals(reason)) {
244:             paymentWorker.markFailed(paymentId, reason);
245:         }
246:     }
247: 
248:     private String codErrorMessage(String reason) {
249:         return switch (reason) {
250:             case "ALREADY_HANDLED" -> "This request has already been handled";
251:             case "ALREADY_SOLD" -> "This item has already been sold";
252:             case "PAYMENT_NOT_FOUND" -> "Payment not found";
253:             default -> "Could not update this request. Please try again.";
254:         };
255:     }
256: 
257:     private void notifyCodRequest(Payment payment) {
258:         Listings listing = payment.getListing();
259:         String title = (listing != null) ? listing.getTitle() : "listing";
260: 
261:         try {
262:             emailServices.sendCodRequestEmail(
263:                     payment.getSeller().getEmail(),
264:                     title,
265:                     payment.getBuyer().getUsername(),
266:                     payment.getAmount());
267:         } catch (Exception e) {
268:             log.error("[COD] request email failed for payment #{}", payment.getId(), e);
269:         }
270: 
271:         try {
272:             notificationService.sendToUser(payment.getSeller().getId(), "COD_REQUEST", Map.of(
273:                     "paymentId", payment.getId(),
274:                     "listingId", listing != null ? listing.getId() : 0L,
275:                     "listingTitle", title,
276:                     "buyerName", payment.getBuyer().getUsername(),
277:                     "amount", payment.getAmount().toPlainString(),
278:                     "imgUrl", (listing != null && listing.getImgUrl() != null) ? listing.getImgUrl() : ""));
279:         } catch (Exception e) {
280:             log.error("[COD] notification failed for payment #{}", payment.getId(), e);
281:         }
282:     }
283: 
284:     private void notifyCodDecision(Long paymentId, boolean accepted) {
285:         paymentRepository.findById(paymentId).ifPresent(payment -> {
286:             Listings listing = payment.getListing();
287:             String title = (listing != null) ? listing.getTitle() : "listing";
288:             String message = accepted
289:                     ? "Your cash-on-delivery request for '" + title + "' was accepted."
290:                     : "Your cash-on-delivery request for '" + title + "' was declined.";
291: 
292:             try {
293:                 if (accepted) {
294:                     emailServices.sendCodAcceptedEmail(payment.getBuyer().getEmail(), title);
295:                 } else {
296:                     emailServices.sendCodDeclinedEmail(payment.getBuyer().getEmail(), title);
297:                 }
298:             } catch (Exception e) {
299:                 log.error("[COD] decision email failed for payment #{}", paymentId, e);
300:             }
301: 
302:             try {
303:                 notificationService.sendToUser(payment.getBuyer().getId(), "COD_DECISION", Map.of(
304:                         "title", accepted ? "Request accepted" : "Request declined",
305:                         "message", message,
306:                         "type", accepted ? "success" : "error",
307:                         "paymentId", paymentId,
308:                         "listingId", listing != null ? listing.getId() : 0L,
309:                         "status", payment.getStatus().name(),
310:                         "accepted", accepted));
311:             } catch (Exception e) {
312:                 log.error("[COD] decision notification failed for payment #{}", paymentId, e);
313:             }
314:         });
315:     }
316: }

